begin;
do $$ declare t text; n integer; checks integer:=0; begin
foreach t in array array['care_team_assignments','patient_site_enrollments','staff_site_assignments','restricted_record_flags','restricted_record_opens','advocates','advocate_links','referrals','referral_codes','referral_status_updates','referral_outreach_log','signup_sessions','signup_attempts','signup_safety_scans','identity_review_items','account_support_items','website_inbox_items','intake_checklists','intake_form_status','intake_packet_needs','pre_chart_triage','first_visit_handoffs','staging_imports','staging_rows','packet_documents','on_call_shifts'] loop
if not (select relrowsecurity from pg_class where oid=('public.'||t)::regclass) then raise exception 'rls_missing %',t; end if;
if exists(select 1 from pg_policies where schemaname='public' and tablename=t and qual<>'false') then raise exception 'phase2_read_open %',t; end if;
if has_table_privilege('authenticated','public.'||t,'INSERT') or has_table_privilege('authenticated','public.'||t,'UPDATE') or has_table_privilege('authenticated','public.'||t,'DELETE') or has_table_privilege('service_role','public.'||t,'INSERT') or has_table_privilege('service_role','public.'||t,'UPDATE') or has_table_privilege('service_role','public.'||t,'DELETE') or has_table_privilege('anon','public.'||t,'SELECT') then raise exception 'direct_grant_open %',t; end if; checks:=checks+1; end loop;
if has_function_privilege('authenticated','public.phase2_command(text,uuid,jsonb,text)','execute') or has_function_privilege('authenticated','app.phase2_run_action(text,uuid,jsonb,text)','execute') or has_function_privilege('authenticated','public.phase2_packet_documents(uuid)','execute') or has_function_privilege('authenticated','public.advocate_view_identity(uuid)','execute') then raise exception 'phase2_rpc_open'; end if; checks:=checks+1;
if exists(select 1 from information_schema.columns where table_schema='public' and table_name in ('signup_safety_scans','pre_chart_triage') and column_name in ('text','message','answers','raw_text','note')) then raise exception 'safety_text_shape'; end if; checks:=checks+1;
if exists(select 1 from information_schema.columns where table_schema='public' and table_name='identity_review_items' and column_name in ('resume_name','request_code','channel')) then raise exception 'lane_mixed'; end if; checks:=checks+1;
if (select count(*) from public.packet_documents where storage_path is not null)<>0 then raise exception 'packet_storage_open'; end if; checks:=checks+1;
if checks<>30 then raise exception 'closure_count'; end if; end $$; rollback;